cd "C:/Users/SALEAD~1/AppData/Local/Temp/claude/c--Users-SALEADMIN-Downloads-Oekovolt-Web-DE-Oekovolt-Web-DE/6ac8640b-bab4-4de9-9c07-3a24f91b0e42/scratchpad/check"; cat > modell.mjs <<'EOF'
import { FREIFLAECHE, ERLOESE, FINANZIERUNG, PACHT, PHASEN, regionById, irr, npv, annuitaet } from "file:///C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/lib/invest/markt.js";
const MWP=10, KWP=MWP*1000, KABEL_M=2000;
const RTB = PHASEN.find(p=>p.id==="rtb");
function berechne({ preisFaktor=1, capexFaktor=1, zins=FINANZIERUNG.zins }={}) {
  const reg = regionById("de-sued");
  const epc = FREIFLAECHE.capexProKwp.mittel*KWP;
  const netz = FREIFLAECHE.netzanschlussFixProMwp*MWP + FREIFLAECHE.kabelProMeter*KABEL_M;
  const projektrechte = (RTB.preisProKwp.min+RTB.preisProKwp.max)/2*KWP;
  const capex = (epc+netz)*capexFaktor + projektrechte;
  const ha = MWP*FREIFLAECHE.haProMwp;
  const fk = capex*FINANZIERUNG.fremdkapitalQuote, ek = capex-fk;
  const rate = annuitaet(fk, zins, FINANZIERUNG.tilgungJahre);
  const proj=[-capex], eig=[-ek]; let dscrMin=Infinity, summeErloes=0;
  for (let t=1;t<=FREIFLAECHE.laufzeit;t++){
    const kwh = KWP*reg.ertrag*Math.pow(1-FREIFLAECHE.degradation,t-1);
    const ct = (t<=20?ERLOESE.eegFreiflaecheCt:ERLOESE.merchantCt)*preisFaktor;
    const erl = kwh*ct/100;
    const opex = FREIFLAECHE.opexProKwp*KWP*Math.pow(1+FREIFLAECHE.inflation,t-1);
    const pacht = ha*PACHT.freiflaecheProHa.mittel*Math.pow(1+PACHT.indexierung,t-1);
    let cf = erl-opex-pacht;
    if (t===FREIFLAECHE.laufzeit) cf -= FREIFLAECHE.rueckbauProKwp*KWP;
    proj.push(cf);
    const ds = t<=FINANZIERUNG.tilgungJahre?rate:0;
    if (ds) dscrMin=Math.min(dscrMin,cf/ds);
    eig.push(cf-ds);
    if(t===1) summeErloes = {erl,opex,pacht,kwh};
  }
  return { capex, epc, netz, projektrechte, fk, ek, rate, ha, j1: summeErloes, projIrr: irr(proj), ekIrr: irr(eig), ekNpv: npv(FINANZIERUNG.diskont, eig), dscrMin };
}
console.log(berechne());
for (const f of [0.9,1.1]) console.log("preis",f, berechne({preisFaktor:f}).projIrr, berechne({preisFaktor:f}).ekIrr);
for (const f of [0.9,1.1]) console.log("capex",f, berechne({capexFaktor:f}).projIrr, berechne({capexFaktor:f}).ekIrr);
for (const z of [0.035,0.055]) console.log("zins",z, berechne({zins:z}).projIrr, berechne({zins:z}).ekIrr);
EOF
node modell.mjs 2>/dev/null

